import{_ as a,a as o,b as t,c as r,d as s,e as n}from"./chunks/19-saaw-governed-self-morphing-v2.CtEM6EK-.js";import{_ as l,o as i,c as p,a2 as c}from"./chunks/framework.Cm6XCzck.js";const _=JSON.parse('{"title":"Trace ≠ Governance：从工作事实到 SaaW","description":"","frontmatter":{"title":"Trace ≠ Governance：从工作事实到 SaaW","date":"2026-08-14","column":"industry-architecture","category":"visual-essay","version":"V1.0","summary":"从执行轨迹与治理的根本区别出发，解释 TMPA、FCoP、CodeFlowMu、元开发运行体、数字员工包与受治理 Self-Morphing 如何形成通向 SaaW 的工程链。","item_id":"VISUAL-ESSAY-20260814-TRACE-GOVERNANCE-SAAW","lifecycle":"Published","cover":"/assets/covers/01-saaw-manifesto-cover-agent-worker.png","visualization":"/assets/covers/16-saaw-tmpa-four-rules-v2.svg","visualization_2":"/assets/covers/17-saaw-fcop-lifecycle-v2.svg","visualization_3":"/assets/covers/18-saaw-codeflowmu-runtime-boundary-v2.svg","visualization_4":"/assets/covers/19-saaw-governed-self-morphing-v2.svg","evidence_status":"Derived from the published SaaW V1.1 manifesto and TMPA V1.0 publication line","citation_status":"TMPA V1.0 DOI and public engineering repositories linked","editing_status":"Published","publication_authorized":true,"outline":"deep"},"headers":[],"relativePath":"zh/industry/2026-08-14-trace-governance-saaw-visual-essay.md","filePath":"zh/industry/2026-08-14-trace-governance-saaw-visual-essay.md","lastUpdated":1786641132000}'),d={name:"zh/industry/2026-08-14-trace-governance-saaw-visual-essay.md"};function g(u,e,h,m,f,v){return i(),p("div",null,[...e[0]||(e[0]=[c('<h1 id="trace-governance-从工作事实到-saaw" tabindex="-1">Trace ≠ Governance：从工作事实到 SaaW <a class="header-anchor" href="#trace-governance-从工作事实到-saaw" aria-label="Permalink to &quot;Trace ≠ Governance：从工作事实到 SaaW&quot;">​</a></h1><h2 id="tmpa、fcop、codeflowmu-与-self-morphing-的一条工程链" tabindex="-1">TMPA、FCoP、CodeFlowMu 与 Self-Morphing 的一条工程链 <a class="header-anchor" href="#tmpa、fcop、codeflowmu-与-self-morphing-的一条工程链" aria-label="Permalink to &quot;TMPA、FCoP、CodeFlowMu 与 Self-Morphing 的一条工程链&quot;">​</a></h2><p><a href="/joinwell52/zh/industry/2026-08-10-saaw-software-as-an-agent-worker">阅读《从 SaaS 到 SaaW》23 节完整原文</a></p><p><a href="/joinwell52/en/industry/2026-08-14-trace-governance-saaw-visual-essay">English version</a></p><p><a href="/joinwell52/assets/covers/01-saaw-manifesto-cover-agent-worker.png"><img src="'+a+'" alt="SaaW — Software as an Agent Worker"></a></p><p>一个 Agent 调用了工具，修改了文件，最后返回 <code>completed</code>。</p><p>这说明什么？</p><p>它只能说明：<strong>发生过一次执行。</strong></p><p>它不能自动证明：任务已经合法完成、测试已经确认、交付已经被审查、冲突已经解决，或者某个角色有权把任务推进到下一状态。</p><p>这正是长期 Agent 系统最容易忽略的架构分界：</p><blockquote><p><strong>Trace（执行轨迹）≠ Governance（治理）。</strong></p></blockquote><p><a href="/joinwell52/assets/covers/15-saaw-trace-vs-governance-v2.svg"><img src="'+o+'" alt="Trace 不等于 Governance：执行轨迹与治理状态的区别"></a></p><p><em>图 1：Trace 记录事件；Governance 根据持久工作事实、规则、责任与授权重建合法状态。</em></p><h2 id="_1-执行轨迹为什么不够" tabindex="-1">1. 执行轨迹为什么不够 <a class="header-anchor" href="#_1-执行轨迹为什么不够" aria-label="Permalink to &quot;1. 执行轨迹为什么不够&quot;">​</a></h2><p>轨迹适合回答：模型调用了什么工具、操作发生在什么时候、返回了什么结果。</p><p>但一项真实工作还需要回答另一组问题：</p><ul><li>谁授权了任务？</li><li>谁正式接受了责任？</li><li>哪个产物代表正式交付？</li><li>测试结果是否可复核？</li><li>谁进行了独立审查？</li><li>当前生命周期状态是否合法？</li><li>冲突、缺口和悬空引用是否仍然存在？</li><li>进程重启后，应该由谁继续？</li></ul><p>这些问题不是增加几行日志就能解决的。日志仍然只是系统事件；治理关心的是工作事实、责任关系和决策效力。</p><p>因此，构建数字员工的第一步，不是让 Agent 调用更多工具，而是让工作事实脱离 Agent 会话而存在。</p><h2 id="_2-tmpa-让工作事实可以重建" tabindex="-1">2. TMPA：让工作事实可以重建 <a class="header-anchor" href="#_2-tmpa-让工作事实可以重建" aria-label="Permalink to &quot;2. TMPA：让工作事实可以重建&quot;">​</a></h2><p>**TMPA（Textual Multi-Agent Process Architecture，文本化多智能体流程架构）**是一种面向中小企业、最低基础设施条件的文本消息多智能体异步流程架构。</p><p>它不是 Agent 调度器，也不是一个中央运行时。TMPA 讨论的是：多个 Agent 与人长期异步协作时，任务、责任、证据、冲突与审计状态如何成立。</p><p>其核心由四条相互关联的规则构成：</p><blockquote><p><strong>文本承载持久消息与状态；每个写者保持自己的局部串行流；多条串行流异步推进并形成并行协作；读端聚合现有证据，重建流程、责任、生命周期、冲突与审计状态。</strong></p></blockquote><p><a href="/joinwell52/assets/covers/16-saaw-tmpa-four-rules-v2.svg"><img src="'+t+'" alt="TMPA 四条规则与事实重建"></a></p><p><em>图 2：每个主体只追加自己的事实；跨流引用形成偏序关系；Reader 聚合证据但不覆盖冲突。</em></p><p>这里最关键的不是“用文本代替数据库”，而是两个更基本的原则：</p><p>第一，责任必须有明确来源。PM、DEV、QA 和人类决策者分别保持自己的局部事实流，不去修改另一个主体已经写下的历史。</p><p>第二，状态不是最后一个字段值。Reader 根据 <code>Task</code>、<code>Acceptance</code>、<code>Report</code>、<code>Review</code>、<code>Decision</code>、<code>Issue</code> 和 <code>Correction</code> 等对象重新计算当前状态。</p><p>于是，模型可以替换，进程可以重启，但已经成立的工作事实不会随会话一起消失。</p><h2 id="_3-fcop-让治理语义进入项目协作" tabindex="-1">3. FCoP：让治理语义进入项目协作 <a class="header-anchor" href="#_3-fcop-让治理语义进入项目协作" aria-label="Permalink to &quot;3. FCoP：让治理语义进入项目协作&quot;">​</a></h2><p>理论与规范需要一种可运行的协作表达。</p><p><strong>FCoP（File-based Coordination Protocol，文件驱动协作协议）是一种以文件系统为唯一同步原语的多智能体行为治理协议。</strong></p><p>FCoP 的项目可见 Profile 可以概括为：</p><ul><li><strong>目录即状态</strong>：<code>inbox → active → review → done → archive</code>；</li><li><strong>文件名即路由</strong>：发送者、接收者、对象类型与序号共同表达身份；</li><li><strong>内容即负载</strong>：Markdown 与 frontmatter 承载任务、报告、引用和证据；</li><li><strong>原子移动即同步</strong>：生命周期迁移通过 <code>os.rename()</code> 完成。</li></ul><p><a href="/joinwell52/assets/covers/17-saaw-fcop-lifecycle-v2.svg"><img src="'+r+'" alt="FCoP 文件驱动生命周期与事实平面"></a></p><p><em>图 3：生命周期变化不是覆盖中央 status，而是移动项目可见工作对象；人、Agent、Reader 与运维工具观察同一事实平面。</em></p><p>FCoP 的价值不只是“用文件传消息”。它让任务交接、报告、复核、决策、问题和恢复路径可以观察、引用和审计。</p><p>但边界也必须明确：FCoP 治理协作行为，不负责模型推理、进程调度、身份认证或资源分配，也不是完整的 Agent Runtime。</p><h2 id="_4-codeflowmu-让角色、工具和治理进入真实运行" tabindex="-1">4. CodeFlowMu：让角色、工具和治理进入真实运行 <a class="header-anchor" href="#_4-codeflowmu-让角色、工具和治理进入真实运行" aria-label="Permalink to &quot;4. CodeFlowMu：让角色、工具和治理进入真实运行&quot;">​</a></h2><p>如果说 TMPA 定义的是工作事实与治理语义，FCoP 提供项目可见的文件驱动协作协议，那么 <strong>CodeFlowMu 解决的是这些语义和协议如何进入真实 Agent 运行世界。</strong></p><p>它的工程起点不是构造一个巨大的中央 Agent 运行体。</p><p>推理交给成熟模型生态；浏览器、API、CLI、MCP 和业务系统负责实际动作；CodeFlowMu 集中处理角色编排、责任边界、Skill 调用、生命周期、FCoP 接入、报告、审查、恢复与人类决策。</p><p><a href="/joinwell52/assets/covers/18-saaw-codeflowmu-runtime-boundary-v2.svg"><img src="'+s+'" alt="CodeFlowMu 工程运行边界"></a></p><p><em>图 4：模型负责推理，工具负责行动；CodeFlowMu 组织工作，FCoP 承载事实，TMPA 指导治理语义。</em></p><p>因此，三者不是三个相似的产品：</p><table tabindex="0"><thead><tr><th>层次</th><th>解决的问题</th><th>不负责什么</th></tr></thead><tbody><tr><td>TMPA</td><td>什么工作事实可以成立和重建</td><td>不调度或执行工作</td></tr><tr><td>FCoP</td><td>这些事实如何进入项目可见协作</td><td>不是完整 Agent Runtime</td></tr><tr><td>CodeFlowMu</td><td>角色、工具、协议和治理如何真实运行</td><td>不用运行事件替代业务决策</td></tr></tbody></table><p>把边界分清，才能避免把“Agent 返回完成”误当成“组织已经接受交付”。</p><h2 id="_5-元开发运行体-研发能力成为生产能力" tabindex="-1">5. 元开发运行体：研发能力成为生产能力 <a class="header-anchor" href="#_5-元开发运行体-研发能力成为生产能力" aria-label="Permalink to &quot;5. 元开发运行体：研发能力成为生产能力&quot;">​</a></h2><p>CodeFlowMu 当前最值得关注的地方，不只是多个 Agent 可以一起开发软件。</p><blockquote><p><strong>更重要的是，这种研发能力本身可以成为下一代数字员工的生产能力。</strong></p></blockquote><p>我们把这一形态称为 <strong>元开发运行体（Meta-Development Runtime）</strong>。</p><p>PM、DEV、QA、OPS 等角色不仅可以开发传统软件，还可以把岗位职责、工作流、Skill、权限、治理策略、验证规则、运行配置、恢复规则和人类决策门组合成：</p><blockquote><p><strong>数字员工包（Digital Employee Package）：让数字员工成为可工程化产品。</strong></p></blockquote><p>它使岗位能力可以像软件一样被定义、开发、测试、版本化、部署、升级和回滚。</p><h2 id="_6-self-morphing-受治理地-自己开发自己" tabindex="-1">6. Self-Morphing：受治理地“自己开发自己” <a class="header-anchor" href="#_6-self-morphing-受治理地-自己开发自己" aria-label="Permalink to &quot;6. Self-Morphing：受治理地“自己开发自己”&quot;">​</a></h2><p><strong>Self-Morphing</strong> 不是让生产环境中的 Agent 任意重写自己，也不是无限递归地制造 Agent。</p><p>它描述的是一个严格隔离并可回滚的改进闭环：生产运行产生工作证据；证据暴露能力缺口；元开发运行体设计改进并生成新版本数字员工包；新版本经过隔离验证和明确授权后，才允许进入下一轮工作。</p><p><a href="/joinwell52/assets/covers/19-saaw-governed-self-morphing-v2.svg"><img src="'+n+'" alt="受治理的元开发与 Self-Morphing 闭环"></a></p><p><em>图 5：证据可以进入元开发，但元开发不能在线改写生产运行体；验证与授权决定能否部署，并始终保留回滚路径。</em></p><p>完整循环是：</p><blockquote><p><strong>工作 → 证据 → 发现缺口 → 开发改进 → 隔离验证 → 人类或治理授权 → 部署 → 新一轮工作</strong></p></blockquote><p>如果变更来源不可追踪、测试不可复现、部署未经授权、运行版本不可识别，或者失败后无法回滚，那么所谓“自我演化”就只是不可审计的自动改写。</p><h2 id="_7-人类没有消失-而是离开了操作层" tabindex="-1">7. 人类没有消失，而是离开了操作层 <a class="header-anchor" href="#_7-人类没有消失-而是离开了操作层" aria-label="Permalink to &quot;7. 人类没有消失，而是离开了操作层&quot;">​</a></h2><p>SaaW 并不意味着把人从系统里删除。</p><p>低风险、可逆、策略内的查询、整理、验证、报告和同步，可以逐步由数字员工执行；外部发布、不可逆修改、资金、凭证、隐私和策略例外，则必须停在人类授权边界之前。</p><p>人不再负责每一次点击和信息搬运，而是负责：</p><ul><li>设定目标与权限边界；</li><li>处理冲突和异常；</li><li>审查关键证据；</li><li>批准、拒绝或要求返工；</li><li>对高影响后果承担最终责任。</li></ul><p>在 SaaS 中，人通常停留在软件操作层；在 SaaW 中，人逐渐进入治理和最终授权层。</p><h2 id="_8-saaw-软件开始承担工作" tabindex="-1">8. SaaW：软件开始承担工作 <a class="header-anchor" href="#_8-saaw-软件开始承担工作" aria-label="Permalink to &quot;8. SaaW：软件开始承担工作&quot;">​</a></h2><p>**SaaW（Software as an Agent Worker）**是整条变化的上位名称：软件不再只是被人操作的功能集合，而开始在明确的岗位职责、权限边界和治理规则下持续承担工作。</p><p>它不是新的聊天框，也不是只增加一个 Agent。一个真正的数字工作主体需要角色、环境、Skill、权限、状态、治理、证据、恢复能力和人类授权边界。</p><p>这里仍然需要区分已经验证的能力与研究方向。</p><p>当前可以公开检查的工程基础包括 TMPA V1.0 的架构论文、核心规范和实施案例，FCoP 的文件驱动协议与实现，以及 CodeFlowMu 的开放工程运行环境。实施案例固定 CodeFlowMu v1.8.0，并记录对 TMPA S1.0 的 <strong>14/14</strong> 验证结果。</p><p>标准化数字员工包、标准化 Agent PC、领域工作运行体和更广泛的 Self-Morphing，仍然属于研究与后续工程验证范围。</p><h2 id="结语" tabindex="-1">结语 <a class="header-anchor" href="#结语" aria-label="Permalink to &quot;结语&quot;">​</a></h2><p>从 Agent 系统到数字员工，最关键的变化并不是模型更像人，而是工作开始拥有独立于模型会话的事实、责任、证据、恢复和授权结构。</p><blockquote><p><strong>TMPA 让工作事实成立，FCoP 让协作事实可见，CodeFlowMu 让它们进入真实运行；元开发运行体再把运行证据生产为数字员工包，并通过受治理的 Self-Morphing 持续改进，最终指向 SaaW。</strong></p></blockquote><p>软件曾经是工具。<br> 后来成为服务。<br> 现在，它正在开始工作。</p><blockquote><p><strong>从软件市场到数字劳动力市场。</strong></p></blockquote><hr><ul><li><strong>完整原文：</strong> <a href="/joinwell52/zh/industry/2026-08-10-saaw-software-as-an-agent-worker">从 SaaS 到 SaaW：当代码库开始“自己开发自己”</a></li><li><strong>TMPA V1.0 DOI：</strong> <a href="https://doi.org/10.5281/zenodo.21888488" target="_blank" rel="noreferrer">10.5281/zenodo.21888488</a></li><li><strong>FCoP：</strong> <a href="https://github.com/joinwell52-AI/FCoP" target="_blank" rel="noreferrer">GitHub Repository</a></li><li><strong>CodeFlowMu：</strong> <a href="https://github.com/joinwell52-AI/CodeFlowMu-open" target="_blank" rel="noreferrer">Open Engineering Runtime</a></li><li><strong>版本状态：</strong> V1.0 · 已发布</li></ul>',82)])])}const b=l(d,[["render",g]]);export{_ as __pageData,b as default};
